import {STATION_REFERENCES213} from './station-reference213.js?v=215';
// Review all 39 stations against the supplied photos, using the actual simulator.
import {SURFACE209,platformEye209} from './station-layout208.js?v=209';
const $=id=>document.getElementById(id),sleep=ms=>new Promise(r=>setTimeout(r,ms));
async function ready(test){for(let i=0;i<600;i++){if(test())return;await sleep(100);}throw Error('No terminó la carga. Recarga e inténtalo de nuevo.');}
function closePanel209(){const p=$('coyuya-review208');p?.cleanup209?.();p?.remove();document.body.dataset.coyuyaPreview208='false';}
async function openPreview208(button,id='L8-10'){
 const reference=STATION_REFERENCES213[id];if(!reference)return;const spec={...(SURFACE209[id]||{name:id,kind:'existing'})};const lineNumber=Number(id[1]);button.disabled=true;button.textContent='Preparando '+spec.name+'…';
 try{
  await ready(()=>window.metroGame&&window.metroViewState);
  if(document.body.dataset.gameScreen!=='simulation'||window.metroViewState().currentLine!==lineNumber)await window.metroGame.choose('automatic',lineNumber);
  if(window.metroViewState().currentLine!==lineNumber)$('line'+lineNumber).click();await ready(()=>window.stationScene&&window.metroViewState().currentLine===lineNumber&&document.body.dataset.loading142!=='true');
  closePanel209();document.body.dataset.coyuyaPreview208='true';if(!$('coyuya-style208')){const style=document.createElement('style');style.id='coyuya-style208';style.textContent='body[data-coyuya-preview208=true] #sim106-stopped{display:none}';document.head.append(style);}
  const state=window.metroViewState();if(state.running)$('play').click();const line=state.engine.lines[lineNumber],index=line.stations.findIndex(s=>s.id===id),center=line.distances[index];spec.name=line.stations[index].nombre;
  const trains=state.engine.trains.filter(t=>t.line===lineNumber);for(const direction of[-1,1]){const t=trains.find(t=>t.direction===direction);if(t){t.position=center;t.target=index;t.wait=Math.max(8,state.engine.stopDuration(t)-3);t.speed=0;t.state='Revisión de andenes';}}
  const train=trains.find(t=>t.direction===1)||trains[0];window.selectSceneTrain(train.id);window.pinSceneStation(id);const view=window.stationScene;view.lastStation=-1;view.setCamera('full',true);await view.ready142();
  const panel=document.createElement('section');panel.id='coyuya-review208';panel.setAttribute('aria-label','Revisión fotográfica de estaciones');panel.style.cssText='position:fixed;bottom:18px;right:18px;z-index:110;width:min(390px,calc(100vw - 36px));max-height:calc(100vh - 110px);overflow:auto;box-sizing:border-box;padding:12px;background:#122b2ef2;color:#fff;border:1px solid #66857b;border-radius:12px;font:14px Arial;box-shadow:0 5px 22px #0005';
  const kind=spec.kind==='terminal'?'Dos islas · tres vías':spec.kind==='lateral'?'Dos andenes laterales':spec.kind==='island'?'Andén central':'Acabados por referencia';
  panel.innerHTML='<strong></strong><p style="margin:6px 0 8px;font-size:12px"></p><label>Estación <select aria-label="Estación para revisar" style="width:100%;margin:6px 0 10px;padding:6px"></select></label><div style="display:flex;gap:6px;flex-wrap:wrap"><button data-view208="detail">Detalle de andenes</button><button data-view208="full">Vista general</button><button data-view208="top">Planta sin cubierta</button><button data-view208="passenger">Caminar por el andén</button><button data-view208="other">Cambiar de andén</button><button data-view208="run">Probar circulación</button><button data-view208="close">Ocultar panel</button></div>';
  panel.querySelector('strong').textContent=spec.name+' · '+kind;panel.querySelector('p').textContent='Vías y planta conservadas. Dimensiones y zonas ocultas aproximadas.'+(spec.kind==='terminal'?' Vía central sin servicio automático.':'');
  const selector=panel.querySelector('select');for(const value of [...state.engine.lines[1].stations,...state.engine.lines[8].stations]){const key=value.id;const option=document.createElement('option');option.value=key;option.textContent='L'+key[1]+' · '+value.nombre;option.selected=key===id;selector.append(option);}selector.onchange=()=>openPreview208(button,selector.value);
  const comparison=document.createElement('details');comparison.style.cssText='margin-top:10px;font-size:12px';const summary=document.createElement('summary');summary.textContent='Fotografía de referencia';summary.style.cursor='pointer';comparison.append(summary);const figure=document.createElement('figure');figure.style.margin='8px 0 0';const photo=document.createElement('img');photo.alt='Fotografía aportada de '+spec.name;photo.style.cssText='display:block;max-width:100%;max-height:220px;margin:auto;object-fit:contain';const caption=document.createElement('figcaption');caption.textContent=reference.note;caption.style.cssText='margin-top:6px;line-height:1.4';figure.append(photo,caption);comparison.append(figure);comparison.addEventListener('toggle',()=>{if(comparison.open&&!photo.getAttribute('src'))photo.src=reference.photo;});panel.append(comparison);
  let islandSide=-1;
  for(const b of panel.querySelectorAll('button')){b.style.cssText='padding:8px;border:1px solid #8da99c;border-radius:6px;background:#254b45;color:white;cursor:pointer';if(b.dataset.view208==='other')b.hidden=spec.kind==='island';b.onclick=()=>{
   const mode=b.dataset.view208;if(mode==='close'){closePanel209();return;}if(mode==='run'){$('play').click();b.textContent=window.metroViewState().running?'Pausar circulación':'Probar circulación';return;}
   if(mode==='other')islandSide=-islandSide;view.setCamera(mode==='passenger'||mode==='other'?'passenger':'full',true);
   if(mode==='passenger'||mode==='other'){view.platformSide169=islandSide;view.camera.position.z=Math.abs(SURFACE209[id]?platformEye209(id):-5.6)*islandSide;view.controls.target.z=view.camera.position.z;view.previousPlatform169=null;view.passenger178.enter();}
   else{$('station-cutaway').checked=true;$('environment-cutaway').checked=true;view.shellState101=null;if(mode==='top'){view.controls.target.set(center,1.2,0);view.camera.position.set(center,260,.01);}else if(mode==='detail'){view.controls.target.set(center,1.5,0);view.camera.position.set(center-26,28,-48);}else{view.controls.target.set(center,2.5,0);view.camera.position.set(center-45,145,-245);}view.controls.update();}
  };}
  document.body.append(panel);const sync=()=>{panel.hidden=document.body.dataset.gameScreen!=='simulation'||window.metroViewState?.()?.currentLine!==lineNumber;document.body.dataset.coyuyaPreview208=String(!panel.hidden);};const observer=new MutationObserver(sync);observer.observe(document.body,{attributes:true,attributeFilter:['data-game-screen']});panel.cleanup209=()=>observer.disconnect();panel.querySelector('[data-view208="'+(spec.kind==='existing'?'passenger':'detail')+'"]').click();
 }catch(error){button.textContent=error.message;console.error(error);}finally{button.disabled=false;button.textContent='Revisar estaciones y fotografías · L1 y L8';}
}
async function mount(){await ready(()=>$('home180')&&window.metroGame);const host=$('home180').querySelector('.home180-utils')||$('home180'),button=document.createElement('button');button.id='coyuya-open208';button.type='button';button.textContent='Revisar estaciones y fotografías · L1 y L8';button.style.cssText='display:block;padding:12px;margin-top:12px;border:1px solid #9ebcae;border-radius:8px;background:#1d5146;color:white';button.onclick=()=>openPreview208(button);host.append(button);const query=new URLSearchParams(location.search).get('previa');const id=STATION_REFERENCES213[query]?query:query==='observatorio'?'L1-20':query==='coyuya'?'L8-10':null;if(id)await openPreview208(button,id);}
if(typeof document!=='undefined')void mount();
